//
//  SlitherlinkGame.swift
//  A Banana Game
//
//  Brain — Slitherlink. Draw a single closed loop along the grid of dots so that every numbered cell
//  is touched by exactly that many segments of the loop. Tap an edge to cycle it: line → ✕ (a "no"
//  mark to help you think) → blank. Complete one unbroken loop that satisfies every clue to win. A
//  clock is the only way to lose — pure deduction, no luck.
//
//  Boards are generated by growing a random simply-connected blob of cells; its boundary is, by
//  construction, exactly one closed loop, and each clue is read straight off that boundary. Then some
//  clues are blanked out — the hidden loop still satisfies whatever remains, so every board is
//  guaranteed solvable and never starts solved. Higher levels use bigger grids and reveal fewer
//  clues, so level 1 is a gentle read and levels 6–7 are brutal deductions.
//
//  Drawn as a jungle snake: pebbles for the dots, clue numbers on river stones in a sunlit clearing,
//  every line you draw is scaly snake body — each open chain gets a head and a tail, and the finished
//  loop is one snake biting its own tail. ✕ marks are crossed twigs; the clock is a bamboo stalk.
//

import SwiftUI

private nonisolated struct SLCell: Hashable, Sendable { let r: Int; let c: Int }
private nonisolated struct SlitherPuzzle: Sendable { let n: Int; let clues: [[Int?]] }

private enum SLEdge: Hashable {
    case h(Int, Int)   // horizontal edge: dot-row r in 0...n, dot-col c in 0..<n  (dot(r,c)→dot(r,c+1))
    case v(Int, Int)   // vertical edge:   dot-row r in 0..<n, dot-col c in 0...n  (dot(r,c)→dot(r+1,c))
}

enum SlitherlinkGame {
    static let definition = GameDefinition(
        id: "slitherlink",
        title: "Jungle Loop",
        emoji: "🍌",
        genre: .brain,
        levelCount: 7,
        manual: GameManual(
            bullets: [
                "Tap an edge between two dots to draw a segment; tap again for ✕, once more to clear.",
                "Build ONE closed loop with no branches or crossings.",
                "Each numbered cell must have exactly that many of its four sides on the loop.",
                "Finish the loop and satisfy every clue before time runs out.",
            ],
            bulletsVI: [
                "Chạm cạnh giữa hai chấm để vẽ một đoạn; chạm lần nữa thành ✕, thêm lần nữa để xóa.",
                "Tạo MỘT vòng khép kín, không rẽ nhánh, không cắt nhau.",
                "Mỗi ô có số phải có đúng bấy nhiêu cạnh (trong bốn cạnh) nằm trên vòng.",
                "Hoàn thành vòng và thỏa mọi gợi ý trước khi hết giờ.",
            ],
            liveDemo: true
        ),
        makeView: { level, onWin, onFail in
            AnyView(SlitherlinkView(level: level, onWin: onWin, onFail: onFail))
        },
        prefetch: { level in SlitherlinkView(level: level, onWin: {}, onFail: {}).prefetchBoard() }
    )
}

struct SlitherlinkView: View {
    let level: Int
    let onWin: () -> Void
    let onFail: () -> Void

    @Environment(\.isDemo) private var isDemo

    private var gridN: Int { [3, 4, 4, 5, 5, 6, 6][min(level, 7) - 1] }
    private var keepFrac: Double { [1.0, 0.85, 0.70, 0.60, 0.50, 0.45, 0.38][min(level, 7) - 1] }
    private var timeLimit: Double { [70, 100, 130, 160, 190, 220, 250][min(level, 7) - 1] }

    private var skyTop: Color { Color(red: 0.12, green: 0.3, blue: 0.16) }
    private var skyBottom: Color { Color(red: 0.04, green: 0.14, blue: 0.07) }

    private enum Phase { case play, done }
    @State private var phase: Phase = .play
    @State private var ready = false
    @State private var n = 0
    @State private var clues: [[Int?]] = []
    @State private var hEdges: [[Int]] = []   // (n+1) x n, 0 blank / 1 line / 2 cross
    @State private var vEdges: [[Int]] = []   // n x (n+1)
    @State private var timeLeft = 0.0
    @State private var loopTask: Task<Void, Never>?
    @State private var demoEdge: SLEdge? = nil    // demo: edge being tapped (ring + finger)

    var body: some View {
        Group {
            if ready { gameBody } else { BrainstormingView(skyTop: skyTop, skyBottom: skyBottom) }
        }
        .task { isDemo ? await runDemo() : await run() }
        .onDisappear { loopTask?.cancel() }
    }

    private var gameBody: some View {
        VStack(spacing: isDemo ? 0 : 8) {
            if !isDemo {
                BambooTimer(frac: timeLimit > 0 ? timeLeft / timeLimit : 0)
                    .frame(height: 22)
                    .padding(.horizontal, 36)
                    .padding(.top, 10)
            }
            boardView
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(JungleFloor().equatable())
        .clipShape(RoundedRectangle(cornerRadius: isDemo ? 12 : 22))
        .padding(.horizontal, isDemo ? 0 : 8)
    }

    private var boardView: some View {
        GeometryReader { geo in
            let pad: CGFloat = isDemo ? 18 : 30
            let w = geo.size.width, h = geo.size.height
            let cell = n > 0 ? min((w - 2 * pad) / CGFloat(n), (h - 2 * pad) / CGFloat(n)) : 0
            let ox = (w - cell * CGFloat(n)) / 2
            let oy = (h - cell * CGFloat(n)) / 2
            Canvas { ctx, _ in drawBoard(ctx, cell: cell, ox: ox, oy: oy, rim: min(cell * 0.38, pad - 6)) }
                .frame(width: w, height: h)
                .contentShape(Rectangle())
                .onTapGesture { loc in
                    if let e = edgeAt(loc, cell: cell, ox: ox, oy: oy) { tap(e) }
                }
        }
    }

    /// The same hit areas the per-edge views had: 0.9 cell along an edge × 0.5 cell across it,
    /// vertical edges checked first (they sat on top).
    private func edgeAt(_ p: CGPoint, cell: CGFloat, ox: CGFloat, oy: CGFloat) -> SLEdge? {
        guard n > 0, cell > 0 else { return nil }
        let fx = (p.x - ox) / cell, fy = (p.y - oy) / cell
        let vc = Int(fx.rounded()), vr = Int(floor(fy))
        if vc >= 0, vc <= n, vr >= 0, vr < n,
           abs(fx - CGFloat(vc)) <= 0.25, abs(fy - (CGFloat(vr) + 0.5)) <= 0.45 { return .v(vr, vc) }
        let hr = Int(fy.rounded()), hc = Int(floor(fx))
        if hr >= 0, hr <= n, hc >= 0, hc < n,
           abs(fy - CGFloat(hr)) <= 0.25, abs(fx - (CGFloat(hc) + 0.5)) <= 0.45 { return .h(hr, hc) }
        return nil
    }

    /// Clearing, clue stones, pebbles, twig ✕s and the snake(s), in one pass.
    private func drawBoard(_ ctx: GraphicsContext, cell: CGFloat, ox: CGFloat, oy: CGFloat, rim: CGFloat) {
        guard n > 0, cell > 0, clues.count == n, hEdges.count == n + 1, vEdges.count == n else { return }
        func dot(_ r: Int, _ c: Int) -> CGPoint { CGPoint(x: ox + CGFloat(c) * cell, y: oy + CGFloat(r) * cell) }
        let board = CGRect(x: ox, y: oy, width: cell * CGFloat(n), height: cell * CGFloat(n))
        SnakeArt.clearing(ctx, board.insetBy(dx: -rim, dy: -rim), cell: cell)
        // Faint scratch lines in the soil mark every edge you can draw on.
        var guide = Path()
        for r in 0...n { guide.move(to: dot(r, 0)); guide.addLine(to: dot(r, n)) }
        for c in 0...n { guide.move(to: dot(0, c)); guide.addLine(to: dot(n, c)) }
        ctx.stroke(guide, with: .color(Color(red: 0.45, green: 0.33, blue: 0.18).opacity(0.22)),
                   style: StrokeStyle(lineWidth: 1, dash: [3, 4]))
        // Clue stones.
        for r in 0..<n {
            for c in 0..<n {
                guard let clue = clues[r][c] else { continue }
                let cnt = clueCount(r, c)
                let state: SnakeArt.StoneState = cnt == clue ? .done : (cnt > clue ? .over : .open)
                SnakeArt.clueStone(ctx, center: CGPoint(x: ox + (CGFloat(c) + 0.5) * cell, y: oy + (CGFloat(r) + 0.5) * cell),
                                   cell: cell, number: clue, state: state)
            }
        }
        // Pebbles at every dot.
        for r in 0...n { for c in 0...n { SnakeArt.pebble(ctx, at: dot(r, c), r: max(2.5, cell * 0.06), seed: r * 31 + c) } }
        // ✕ marks: crossed twigs.
        for r in 0...n { for c in 0..<n where hEdges[r][c] == 2 { SnakeArt.twigs(ctx, at: CGPoint(x: ox + (CGFloat(c) + 0.5) * cell, y: oy + CGFloat(r) * cell), cell: cell) } }
        for r in 0..<n { for c in 0...n where vEdges[r][c] == 2 { SnakeArt.twigs(ctx, at: CGPoint(x: ox + CGFloat(c) * cell, y: oy + (CGFloat(r) + 0.5) * cell), cell: cell) } }
        // The snake: every line edge, then a head and a tail on each open chain.
        var links: [SLCell: [SLCell]] = [:]
        for r in 0...n { for c in 0..<n where hEdges[r][c] == 1 {
            links[SLCell(r: r, c: c), default: []].append(SLCell(r: r, c: c + 1)); links[SLCell(r: r, c: c + 1), default: []].append(SLCell(r: r, c: c))
        } }
        for r in 0..<n { for c in 0...n where vEdges[r][c] == 1 {
            links[SLCell(r: r, c: c), default: []].append(SLCell(r: r + 1, c: c)); links[SLCell(r: r + 1, c: c), default: []].append(SLCell(r: r, c: c))
        } }
        SnakeArt.snakes(ctx, links: links, cell: cell, point: { dot($0.r, $0.c) })
        // Demo press: a ring and a finger on the edge being tapped.
        if let e = demoEdge {
            let (mid, horizontal): (CGPoint, Bool) = {
                switch e {
                case .h(let r, let c): return (CGPoint(x: ox + (CGFloat(c) + 0.5) * cell, y: oy + CGFloat(r) * cell), true)
                case .v(let r, let c): return (CGPoint(x: ox + CGFloat(c) * cell, y: oy + (CGFloat(r) + 0.5) * cell), false)
                }
            }()
            let len = cell * 0.9 + 8, thick = max(3, cell * 0.09) + 14
            let ring = CGRect(x: mid.x - (horizontal ? len : thick) / 2, y: mid.y - (horizontal ? thick : len) / 2,
                              width: horizontal ? len : thick, height: horizontal ? thick : len)
            ctx.stroke(Path(roundedRect: ring, cornerRadius: min(ring.width, ring.height) / 2), with: .color(.white), lineWidth: 2.5)
            var hand = ctx.resolve(Image(systemName: "hand.point.up.left.fill"))
            hand.shading = .color(.white)
            var hctx = ctx
            hctx.addFilter(.shadow(color: .black.opacity(0.6), radius: 3))
            let hw = cell * 0.36
            hctx.draw(hand, in: CGRect(x: mid.x + cell * 0.02, y: mid.y + cell * 0.04, width: hw, height: hw))
        }
    }

    // MARK: - Edge state
    private func edgeState(_ e: SLEdge) -> Int {
        switch e {
        case .h(let r, let c): return r < hEdges.count && c < (hEdges.first?.count ?? 0) ? hEdges[r][c] : 0
        case .v(let r, let c): return r < vEdges.count && c < (vEdges.first?.count ?? 0) ? vEdges[r][c] : 0
        }
    }

    private func tap(_ e: SLEdge) {
        guard phase == .play else { return }
        switch e {
        case .h(let r, let c): hEdges[r][c] = (hEdges[r][c] + 1) % 3
        case .v(let r, let c): vEdges[r][c] = (vEdges[r][c] + 1) % 3
        }
        SoundManager.shared.tap(); Haptics.tap()
        checkWin()
    }

    private func clueCount(_ r: Int, _ c: Int) -> Int {
        (hEdges[r][c] == 1 ? 1 : 0) + (hEdges[r + 1][c] == 1 ? 1 : 0)
            + (vEdges[r][c] == 1 ? 1 : 0) + (vEdges[r][c + 1] == 1 ? 1 : 0)
    }

    // MARK: - Win check
    private func checkWin() {
        // 1. Every shown clue satisfied.
        for r in 0..<n {
            for c in 0..<n {
                if let clue = clues[r][c], clueCount(r, c) != clue { return }
            }
        }
        // 2. Line edges form one single closed loop (every touched dot has degree 2, all connected).
        var adj: [SLCell: [SLCell]] = [:]
        var edgeCount = 0
        func link(_ a: SLCell, _ b: SLCell) { adj[a, default: []].append(b); adj[b, default: []].append(a); edgeCount += 1 }
        for r in 0...n { for c in 0..<n where hEdges[r][c] == 1 { link(SLCell(r: r, c: c), SLCell(r: r, c: c + 1)) } }
        for r in 0..<n { for c in 0...n where vEdges[r][c] == 1 { link(SLCell(r: r, c: c), SLCell(r: r + 1, c: c)) } }
        guard edgeCount > 0 else { return }
        for (_, nbrs) in adj where nbrs.count != 2 { return }
        // Connectivity: one component covering every touched dot.
        guard let start = adj.keys.first else { return }
        var seen: Set<SLCell> = [start]
        var stack = [start]
        while let cur = stack.popLast() {
            for nb in adj[cur] ?? [] where !seen.contains(nb) { seen.insert(nb); stack.append(nb) }
        }
        guard seen.count == adj.count else { return }
        win()
    }

    private func win() {
        guard phase != .done else { return }
        phase = .done; loopTask?.cancel(); onWin()
    }

    private func fail() {
        guard phase != .done else { return }
        phase = .done; loopTask?.cancel(); SoundManager.shared.error(); onFail()
    }

    // MARK: - Demo (live manual clip)
    // Level 1 shows every clue on a 3×3. The demo board is the boundary of an S-shaped region
    //   3 2 0
    //   2 2 2
    //   2 2 3
    // — the only loop matching these clues (checked by enumerating every hole-free region).
    // Through the real `tap`: ✕ the two inner sides of the 0 (two taps each), then trace the
    // 12-edge loop dot to dot; the closing edge passes the real win check.
    private static let demoCrosses: [SLEdge] = [.v(0, 2), .h(1, 2)]
    private static let demoLoop: [SLEdge] = [
        .h(0, 0), .v(0, 1), .h(1, 1), .v(1, 2), .h(2, 2), .v(2, 3),
        .h(3, 2), .h(3, 1), .v(2, 1), .h(2, 0), .v(1, 0), .v(0, 0),
    ]

    private func runDemo() async {
        while !Task.isCancelled {
            n = 3
            clues = [[3, 2, 0], [2, 2, 2], [2, 2, 3]]
            hEdges = Array(repeating: Array(repeating: 0, count: 3), count: 4)
            vEdges = Array(repeating: Array(repeating: 0, count: 4), count: 3)
            demoEdge = nil
            timeLeft = timeLimit
            phase = .play
            ready = true
            try? await Task.sleep(for: .seconds(0.7))
            let script = Self.demoCrosses.map { ($0, 2) } + Self.demoLoop.map { ($0, 1) }
            for (edge, taps) in script {
                guard !Task.isCancelled else { return }
                demoEdge = edge
                for _ in 0..<taps {
                    try? await Task.sleep(for: .seconds(0.15))
                    guard !Task.isCancelled else { return }
                    tap(edge)
                }
                try? await Task.sleep(for: .seconds(0.13))
            }
            demoEdge = nil
            // The closing edge completed the loop → the real win() ran (onWin is a no-op).
            try? await Task.sleep(for: .seconds(1.3))
        }
    }

    // MARK: - Flow
    /// Hands this level's board build to `BoardCache` so it can run during the countdown.
    func prefetchBoard() {
        let gN = gridN, frac = keepFrac
        BoardCache.prefetch(boardKey) { Self.makePuzzle(n: gN, keepFrac: frac) }
    }
    private var boardKey: String { BoardCache.key("slitherlink", level: level) }

    private func run() async {
        let gN = gridN, frac = keepFrac
        let t0 = Date()
        let puzzle = await BoardCache.take(boardKey) { Self.makePuzzle(n: gN, keepFrac: frac) }
        guard !Task.isCancelled else { return }
        await BoardCache.holdBrainstorm(since: t0, minimum: 0.6)
        guard !Task.isCancelled else { return }
        n = puzzle.n
        clues = puzzle.clues
        hEdges = Array(repeating: Array(repeating: 0, count: n), count: n + 1)
        vEdges = Array(repeating: Array(repeating: 0, count: n + 1), count: n)
        ready = true
        phase = .play
        timeLeft = timeLimit
        let start = Date()
        loopTask = Task {
            while !Task.isCancelled && phase == .play {
                try? await Task.sleep(for: .seconds(0.05))
                timeLeft = max(0, timeLimit - Date().timeIntervalSince(start))
                if timeLeft <= 0 { fail(); break }
            }
        }
    }

    // MARK: - Generation (grow a simply-connected blob; its boundary is one loop / off-main)
    private static let dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    private nonisolated static func makePuzzle(n: Int, keepFrac: Double) -> SlitherPuzzle {
        for _ in 0..<300 {
            let blob = growBlob(n)
            guard !blob.isEmpty, blob.count < n * n, simplyConnected(blob, n) else { continue }
            let full = fullClues(blob, n)
            // Need a non-trivial boundary.
            let boundaryCells = full.flatMap { $0 }.filter { $0 > 0 }.count
            guard boundaryCells >= max(4, n) else { continue }
            // Blank a fraction; keep at least a few positive clues so "do nothing" never solves it.
            var cellsList: [SLCell] = []
            for r in 0..<n { for c in 0..<n { cellsList.append(SLCell(r: r, c: c)) } }
            cellsList.shuffle()
            let keepK = max(3, Int((Double(n * n) * keepFrac).rounded()))
            let kept = Set(cellsList.prefix(keepK))
            var clues = [[Int?]](repeating: [Int?](repeating: nil, count: n), count: n)
            var positives = 0
            for r in 0..<n {
                for c in 0..<n where kept.contains(SLCell(r: r, c: c)) {
                    clues[r][c] = full[r][c]
                    if full[r][c] > 0 { positives += 1 }
                }
            }
            guard positives >= 3 else { continue }
            return SlitherPuzzle(n: n, clues: clues)
        }
        return fallback(n)
    }

    private nonisolated static func growBlob(_ n: Int) -> Set<SLCell> {
        let target = Int.random(in: max(2, n)...max(3, Int(Double(n * n) * 0.6)))
        var s: Set<SLCell> = [SLCell(r: Int.random(in: 0..<n), c: Int.random(in: 0..<n))]
        while s.count < target {
            var cand: [SLCell] = []
            for cell in s {
                for (dr, dc) in dirs {
                    let nb = SLCell(r: cell.r + dr, c: cell.c + dc)
                    if nb.r >= 0, nb.r < n, nb.c >= 0, nb.c < n, !s.contains(nb) { cand.append(nb) }
                }
            }
            guard let pick = cand.randomElement() else { break }
            s.insert(pick)
        }
        return s
    }

    /// True if no pocket of non-blob cells is enclosed by the blob (so the boundary is a single loop).
    private nonisolated static func simplyConnected(_ s: Set<SLCell>, _ n: Int) -> Bool {
        let nonCount = n * n - s.count
        if nonCount == 0 { return true }
        var seen = Set<SLCell>()
        var stack: [SLCell] = []
        for r in 0..<n {
            for c in 0..<n where (r == 0 || c == 0 || r == n - 1 || c == n - 1) {
                let cell = SLCell(r: r, c: c)
                if !s.contains(cell) && !seen.contains(cell) { seen.insert(cell); stack.append(cell) }
            }
        }
        while let cur = stack.popLast() {
            for (dr, dc) in dirs {
                let nb = SLCell(r: cur.r + dr, c: cur.c + dc)
                if nb.r >= 0, nb.r < n, nb.c >= 0, nb.c < n, !s.contains(nb), !seen.contains(nb) {
                    seen.insert(nb); stack.append(nb)
                }
            }
        }
        return seen.count == nonCount
    }

    private nonisolated static func fullClues(_ s: Set<SLCell>, _ n: Int) -> [[Int]] {
        func inS(_ r: Int, _ c: Int) -> Bool { r >= 0 && r < n && c >= 0 && c < n && s.contains(SLCell(r: r, c: c)) }
        var out = [[Int]](repeating: [Int](repeating: 0, count: n), count: n)
        for r in 0..<n {
            for c in 0..<n {
                var count = 0
                for (dr, dc) in dirs where inS(r, c) != inS(r + dr, c + dc) { count += 1 }
                out[r][c] = count
            }
        }
        return out
    }

    private nonisolated static func fallback(_ n: Int) -> SlitherPuzzle {
        // A single center cell: its boundary is a unit square. Clues fully shown → always solvable.
        let g = max(n, 3)
        let s: Set<SLCell> = [SLCell(r: g / 2, c: g / 2)]
        let full = fullClues(s, g)
        let clues = full.map { row in row.map { Optional($0) } }
        return SlitherPuzzle(n: g, clues: clues)
    }
}

// MARK: - Jungle snake art

private enum SnakeArt {
    enum StoneState { case open, done, over }
    static let skin = Color(red: 0.36, green: 0.68, blue: 0.22)
    static let skinDark = Color(red: 0.12, green: 0.34, blue: 0.1)
    static let pattern = Color(red: 0.93, green: 0.84, blue: 0.3)

    static func hash(_ n: Double) -> CGFloat {
        let v: Double = sin(n * 12.9898) * 43758.5453
        return CGFloat(v - floor(v))
    }

    /// The sunlit patch of earth the puzzle sits in, with a ring of grass around it.
    static func clearing(_ ctx: GraphicsContext, _ r: CGRect, cell: CGFloat) {
        let shape = Path(roundedRect: r, cornerRadius: cell * 0.45)
        ctx.drawLayer { l in
            l.addFilter(.blur(radius: cell * 0.12))
            l.fill(shape.offsetBy(dx: 0, dy: cell * 0.06), with: .color(.black.opacity(0.35)))
        }
        ctx.fill(shape, with: .radialGradient(Gradient(colors: [Color(red: 0.93, green: 0.84, blue: 0.62), Color(red: 0.8, green: 0.67, blue: 0.44)]),
                                              center: CGPoint(x: r.midX - r.width * 0.15, y: r.midY - r.height * 0.2),
                                              startRadius: 0, endRadius: max(r.width, r.height) * 0.75))
        var specks = Path()
        for k in 0..<Int(r.width * r.height / 90) {
            let x = r.minX + hash(Double(k) * 1.3) * r.width, y = r.minY + hash(Double(k) * 2.9 + 4) * r.height
            specks.addEllipse(in: CGRect(x: x, y: y, width: 1.6, height: 1.2))
        }
        var clip = ctx
        clip.clip(to: shape)
        clip.fill(specks, with: .color(Color(red: 0.5, green: 0.36, blue: 0.2).opacity(0.3)))
        // Grass tufts poking over the rim.
        var tufts = Path()
        let perimeter = 2 * (r.width + r.height)
        let count = Int(perimeter / max(10, cell * 0.22))
        for k in 0..<count {
            let t = CGFloat(k) / CGFloat(count) * perimeter + hash(Double(k)) * 6
            var base: CGPoint
            var inward: CGVector
            if t < r.width { base = CGPoint(x: r.minX + t, y: r.minY); inward = CGVector(dx: 0, dy: 1) }
            else if t < r.width + r.height { base = CGPoint(x: r.maxX, y: r.minY + t - r.width); inward = CGVector(dx: -1, dy: 0) }
            else if t < 2 * r.width + r.height { base = CGPoint(x: r.maxX - (t - r.width - r.height), y: r.maxY); inward = CGVector(dx: 0, dy: -1) }
            else { base = CGPoint(x: r.minX, y: r.maxY - (t - 2 * r.width - r.height)); inward = CGVector(dx: 1, dy: 0) }
            let len = cell * (0.08 + hash(Double(k) + 0.7) * 0.08)
            for s in [-1.0, 0, 1.0] as [CGFloat] {
                tufts.move(to: base)
                tufts.addLine(to: CGPoint(x: base.x + inward.dx * len + inward.dy * s * len * 0.5,
                                          y: base.y + inward.dy * len + inward.dx * s * len * 0.5))
            }
        }
        ctx.stroke(tufts, with: .color(Color(red: 0.3, green: 0.55, blue: 0.2)), style: StrokeStyle(lineWidth: 1.4, lineCap: .round))
    }

    /// A flat river stone with the clue on it — mossy green when met, red when overshot.
    static func clueStone(_ ctx: GraphicsContext, center c: CGPoint, cell: CGFloat, number: Int, state: StoneState) {
        let rx = cell * 0.27, ry = cell * 0.24
        let stone = Path(ellipseIn: CGRect(x: c.x - rx, y: c.y - ry, width: rx * 2, height: ry * 2))
        ctx.fill(stone.offsetBy(dx: cell * 0.02, dy: cell * 0.035), with: .color(.black.opacity(0.22)))
        let base: Color = state == .done ? Color(red: 0.62, green: 0.78, blue: 0.5)
            : (state == .over ? Color(red: 0.93, green: 0.62, blue: 0.56) : Color(red: 0.8, green: 0.8, blue: 0.76))
        ctx.fill(stone, with: .radialGradient(Gradient(colors: [base.lit(0.35), base, base.shade(0.2)]),
                                              center: CGPoint(x: c.x - rx * 0.35, y: c.y - ry * 0.45), startRadius: 0, endRadius: rx * 1.3))
        ctx.stroke(stone, with: .color(base.shade(0.45).opacity(0.7)), lineWidth: 1)
        let ink: Color = state == .done ? Color(red: 0.1, green: 0.36, blue: 0.12)
            : (state == .over ? Color(red: 0.72, green: 0.1, blue: 0.08) : Color(red: 0.22, green: 0.2, blue: 0.18))
        ctx.draw(Text("\(number)").font(.system(size: cell * 0.34, weight: .heavy, design: .rounded)).foregroundColor(ink),
                 at: CGPoint(x: c.x, y: c.y + cell * 0.01))
    }

    static func pebble(_ ctx: GraphicsContext, at p: CGPoint, r: CGFloat, seed: Int) {
        let w = r * (1.9 + hash(Double(seed)) * 0.5), h = r * 1.6
        let shape = Path(ellipseIn: CGRect(x: p.x - w / 2, y: p.y - h / 2, width: w, height: h))
        ctx.fill(shape.offsetBy(dx: 0.8, dy: 1.2), with: .color(.black.opacity(0.25)))
        ctx.fill(shape, with: .radialGradient(Gradient(colors: [Color(white: 0.88), Color(white: 0.55)]),
                                              center: CGPoint(x: p.x - w * 0.2, y: p.y - h * 0.25), startRadius: 0, endRadius: w * 0.7))
    }

    /// Two crossed twigs: the "not here" mark.
    static func twigs(_ ctx: GraphicsContext, at p: CGPoint, cell: CGFloat) {
        let k = cell * 0.11
        var x = Path()
        x.move(to: CGPoint(x: p.x - k, y: p.y - k * 0.9)); x.addLine(to: CGPoint(x: p.x + k, y: p.y + k * 0.9))
        x.move(to: CGPoint(x: p.x + k, y: p.y - k * 0.9)); x.addLine(to: CGPoint(x: p.x - k, y: p.y + k * 0.9))
        ctx.stroke(x, with: .color(Color(red: 0.3, green: 0.18, blue: 0.08)), style: StrokeStyle(lineWidth: max(2.4, cell * 0.05), lineCap: .round))
        ctx.stroke(x, with: .color(Color(red: 0.62, green: 0.42, blue: 0.22)), style: StrokeStyle(lineWidth: max(1.4, cell * 0.03), lineCap: .round))
    }

    /// Scaly body along every drawn edge; each open chain gets a head and a tapered tail, and a closed
    /// loop becomes one snake biting its own tail.
    static func snakes(_ ctx: GraphicsContext, links: [SLCell: [SLCell]], cell: CGFloat, point: (SLCell) -> CGPoint) {
        guard !links.isEmpty else { return }
        let bw = max(5, cell * 0.17)
        var body = Path()
        var drawn = Set<String>()
        for (a, nbrs) in links {
            for b in nbrs {
                let key = a.r < b.r || (a.r == b.r && a.c < b.c) ? "\(a.r),\(a.c)-\(b.r),\(b.c)" : "\(b.r),\(b.c)-\(a.r),\(a.c)"
                guard drawn.insert(key).inserted else { continue }
                body.move(to: point(a)); body.addLine(to: point(b))
            }
        }
        let round = StrokeStyle(lineWidth: bw, lineCap: .round, lineJoin: .round)
        ctx.stroke(body.offsetBy(dx: bw * 0.12, dy: bw * 0.22), with: .color(.black.opacity(0.28)), style: StrokeStyle(lineWidth: bw + 2, lineCap: .round, lineJoin: .round))
        ctx.stroke(body, with: .color(skinDark), style: StrokeStyle(lineWidth: bw + 3, lineCap: .round, lineJoin: .round))
        ctx.stroke(body, with: .color(skin), style: round)
        ctx.stroke(body, with: .color(pattern.opacity(0.85)), style: StrokeStyle(lineWidth: bw * 0.42, lineCap: .butt, lineJoin: .round, dash: [bw * 0.55, bw * 0.75]))
        ctx.stroke(body, with: .color(.white.opacity(0.18)), style: StrokeStyle(lineWidth: bw * 0.18, lineCap: .round, lineJoin: .round))
        // Heads and tails.
        var seen = Set<SLCell>()
        for start in links.keys.sorted(by: { ($0.r, $0.c) < ($1.r, $1.c) }) where !seen.contains(start) {
            var comp: [SLCell] = []
            var stack = [start]
            seen.insert(start)
            while let cur = stack.popLast() {
                comp.append(cur)
                for nb in links[cur] ?? [] where !seen.contains(nb) { seen.insert(nb); stack.append(nb) }
            }
            let degrees = comp.map { links[$0]?.count ?? 0 }
            if degrees.contains(where: { $0 > 2 }) { continue }                  // a branch: no head to give it
            let ends = comp.filter { links[$0]?.count == 1 }.sorted { ($0.r, $0.c) < ($1.r, $1.c) }
            if ends.count == 2 {
                let head = ends[0], tail = ends[1]
                tailTip(ctx, at: point(tail), from: point(links[tail]![0]), bw: bw)
                snakeHead(ctx, at: point(head), from: point(links[head]![0]), bw: bw, biting: false)
            } else if ends.isEmpty, let top = comp.min(by: { ($0.r, $0.c) < ($1.r, $1.c) }), let prev = links[top]?.first {
                // Ouroboros: the head sits on the loop's top-left corner, jaws on its own tail.
                snakeHead(ctx, at: point(top), from: point(prev), bw: bw, biting: true)
            }
        }
    }

    static func tailTip(_ ctx: GraphicsContext, at p: CGPoint, from q: CGPoint, bw: CGFloat) {
        let dx = p.x - q.x, dy = p.y - q.y, len = max(0.001, hypot(dx, dy))
        let ux = dx / len, uy = dy / len
        var tip = Path()
        tip.move(to: CGPoint(x: p.x - uy * bw * 0.5, y: p.y + ux * bw * 0.5))
        tip.addQuadCurve(to: CGPoint(x: p.x + ux * bw * 1.6, y: p.y + uy * bw * 1.6), control: CGPoint(x: p.x + ux * bw * 0.6 - uy * bw * 0.45, y: p.y + uy * bw * 0.6 + ux * bw * 0.45))
        tip.addQuadCurve(to: CGPoint(x: p.x + uy * bw * 0.5, y: p.y - ux * bw * 0.5), control: CGPoint(x: p.x + ux * bw * 0.6 + uy * bw * 0.45, y: p.y + uy * bw * 0.6 - ux * bw * 0.45))
        tip.closeSubpath()
        ctx.stroke(tip, with: .color(skinDark), lineWidth: 3)
        ctx.fill(tip, with: .color(skin))
    }

    /// A friendly cartoon head pointing away from `from`, with eyes and a flicking tongue.
    static func snakeHead(_ ctx: GraphicsContext, at p: CGPoint, from q: CGPoint, bw: CGFloat, biting: Bool) {
        let angle = atan2(p.y - q.y, p.x - q.x)
        var c = ctx
        c.translateBy(x: p.x, y: p.y)
        c.rotate(by: .radians(Double(angle)))
        let hl = bw * 2.1, hw = bw * 1.55
        let headRect = CGRect(x: biting ? -hl * 0.35 : -hl * 0.15, y: -hw / 2, width: hl, height: hw)
        // Tongue first, so the head covers its root.
        if !biting {
            var tongue = Path()
            tongue.move(to: CGPoint(x: headRect.maxX - bw * 0.2, y: 0))
            tongue.addLine(to: CGPoint(x: headRect.maxX + bw * 0.7, y: 0))
            tongue.move(to: CGPoint(x: headRect.maxX + bw * 0.7, y: 0)); tongue.addLine(to: CGPoint(x: headRect.maxX + bw * 1.0, y: -bw * 0.25))
            tongue.move(to: CGPoint(x: headRect.maxX + bw * 0.7, y: 0)); tongue.addLine(to: CGPoint(x: headRect.maxX + bw * 1.0, y: bw * 0.25))
            c.stroke(tongue, with: .color(Color(red: 0.86, green: 0.16, blue: 0.2)), style: StrokeStyle(lineWidth: max(1.2, bw * 0.16), lineCap: .round))
        }
        let head = Path(ellipseIn: headRect)
        c.fill(head, with: .color(skinDark))
        c.fill(Path(ellipseIn: headRect.insetBy(dx: 1.5, dy: 1.5)),
               with: .linearGradient(Gradient(colors: [skin.lit(0.2), skin]), startPoint: CGPoint(x: 0, y: -hw / 2), endPoint: CGPoint(x: 0, y: hw / 2)))
        for s in [-1.0, 1.0] as [CGFloat] {
            let e = CGPoint(x: headRect.minX + hl * 0.62, y: s * hw * 0.26)
            let er = bw * 0.36
            c.fill(Path(ellipseIn: CGRect(x: e.x - er, y: e.y - er, width: er * 2, height: er * 2)), with: .color(.white))
            c.fill(Path(ellipseIn: CGRect(x: e.x - er * 0.1, y: e.y - er * 0.55, width: er * 0.75, height: er * 1.1)), with: .color(.black))
        }
        c.fill(Path(ellipseIn: CGRect(x: headRect.maxX - bw * 0.35, y: -bw * 0.18, width: bw * 0.12, height: bw * 0.12)), with: .color(skinDark))
        c.fill(Path(ellipseIn: CGRect(x: headRect.maxX - bw * 0.35, y: bw * 0.06, width: bw * 0.12, height: bw * 0.12)), with: .color(skinDark))
    }
}

/// Deep jungle around the clearing: leaves and dappled light (static).
private struct JungleFloor: View, Equatable {
    var body: some View {
        Canvas { ctx, s in
            ctx.fill(Path(CGRect(origin: .zero, size: s)),
                     with: .linearGradient(Gradient(colors: [Color(red: 0.1, green: 0.3, blue: 0.15), Color(red: 0.04, green: 0.16, blue: 0.08)]),
                                           startPoint: .zero, endPoint: CGPoint(x: s.width, y: s.height)))
            for k in 0..<46 {
                let x = SnakeArt.hash(Double(k) * 1.7) * s.width
                let y = SnakeArt.hash(Double(k) * 3.3 + 1) * s.height
                let len = 26 + SnakeArt.hash(Double(k) * 5.1) * 44
                let a = Double(SnakeArt.hash(Double(k) * 7.7)) * .pi * 2
                var c = ctx
                c.translateBy(x: x, y: y)
                c.rotate(by: .radians(a))
                var leaf = Path()
                leaf.move(to: .zero)
                leaf.addQuadCurve(to: CGPoint(x: len, y: 0), control: CGPoint(x: len * 0.5, y: -len * 0.34))
                leaf.addQuadCurve(to: .zero, control: CGPoint(x: len * 0.5, y: len * 0.34))
                let tone = 0.22 + Double(SnakeArt.hash(Double(k) * 9.1)) * 0.25
                c.fill(leaf, with: .color(Color(red: tone * 0.45, green: tone * 1.6, blue: tone * 0.55)))
                var vein = Path()
                vein.move(to: .zero); vein.addLine(to: CGPoint(x: len * 0.9, y: 0))
                c.stroke(vein, with: .color(.black.opacity(0.25)), lineWidth: 1)
            }
            for k in 0..<12 {
                let x = SnakeArt.hash(Double(k) * 11.3) * s.width, y = SnakeArt.hash(Double(k) * 13.7) * s.height
                let r = 20 + SnakeArt.hash(Double(k) * 2.1) * 40
                ctx.fill(Path(ellipseIn: CGRect(x: x - r, y: y - r * 0.7, width: r * 2, height: r * 1.4)),
                         with: .radialGradient(Gradient(colors: [Color(red: 1, green: 0.95, blue: 0.6).opacity(0.12), .clear]),
                                               center: CGPoint(x: x, y: y), startRadius: 0, endRadius: r))
            }
        }
        .allowsHitTesting(false)
    }
}

/// The level clock: a bamboo stalk that shortens toward its left end (and dries out near the end).
private struct BambooTimer: View {
    let frac: Double

    var body: some View {
        Canvas { ctx, s in
            let f = CGFloat(max(0, min(1, frac)))
            let len = s.width * f
            guard len > 1 else { return }
            let h = s.height * 0.62
            let r = CGRect(x: 0, y: (s.height - h) / 2, width: len, height: h)
            let green = frac < 0.3 ? Color(red: 0.78, green: 0.62, blue: 0.24) : Color(red: 0.42, green: 0.72, blue: 0.3)
            let stalk = Path(roundedRect: r, cornerRadius: h * 0.35)
            ctx.fill(stalk, with: .linearGradient(Gradient(colors: [green.lit(0.3), green, green.shade(0.3)]),
                                                  startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
            var nodes = Path()
            var x: CGFloat = 34
            while x < len - 4 {
                nodes.addRoundedRect(in: CGRect(x: x - 1.5, y: r.minY - 1, width: 3, height: h + 2), cornerSize: CGSize(width: 1.5, height: 1.5))
                x += 34
            }
            ctx.fill(nodes, with: .color(green.shade(0.4)))
            ctx.stroke(stalk, with: .color(green.shade(0.5)), lineWidth: 1)
            // A leaf sprouting from the live end.
            var leaf = Path()
            let tip = CGPoint(x: len - 6, y: r.minY)
            leaf.move(to: tip)
            leaf.addQuadCurve(to: CGPoint(x: tip.x + 14, y: tip.y - 7), control: CGPoint(x: tip.x + 4, y: tip.y - 9))
            leaf.addQuadCurve(to: tip, control: CGPoint(x: tip.x + 11, y: tip.y + 1))
            ctx.fill(leaf, with: .color(green.lit(0.1)))
        }
        .allowsHitTesting(false)
    }
}

